                if (tick >= 29u)
                    s.Visit(7);
                else if (tick >= 11u)
                    s.Visit(6);
                else if (tick >= 3u)
                    s.Visit(5);
                else
                    s.Visit(4);
                break;
            case 0x0019:
                if (tick >= 29u)
                    s.Visit(11);
